-- Creator Signal OS canonical Supabase schema
create extension if not exists pgcrypto;
create type public.deal_status as enum ('new','processing','needs_review','approved','rejected','archived');
create type public.deal_severity as enum ('info','low','medium','high','critical');
create type public.draft_status as enum ('draft','approved','sent','discarded');
create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null, created_at timestamptz not null default now());
create table public.users (id uuid primary key references auth.users(id) on delete cascade, organization_id uuid not null references public.organizations(id) on delete cascade, full_name text, role text not null default 'manager' check (role in ('owner','manager','coordinator','viewer')), created_at timestamptz not null default now());
create table public.creators (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, name text not null, handle text, email text, categories text[] not null default '{}', active boolean not null default true, created_at timestamptz not null default now());
create table public.rate_cards (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, creator_id uuid not null references public.creators(id) on delete cascade, name text not null, currency char(3) not null default 'USD', effective_from date not null, effective_to date, terms jsonb not null default '{}', created_at timestamptz not null default now());
create table public.brand_contacts (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, brand_name text not null, contact_name text, email text not null, notes text, created_at timestamptz not null default now());
create table public.inbound_deals (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, creator_id uuid references public.creators(id) on delete set null, brand_contact_id uuid references public.brand_contacts(id) on delete set null, provider_event_id text not null, subject text, from_email text, received_at timestamptz not null, raw_text text, normalized_text text, status public.deal_status not null default 'new', extraction jsonb, extraction_confidence numeric(5,4), model_name text, created_at timestamptz not null default now(), unique (organization_id, provider_event_id));
create table public.deal_terms (id uuid primary key default gen_random_uuid(), deal_id uuid not null unique references public.inbound_deals(id) on delete cascade, fee numeric, currency char(3), deliverables jsonb not null default '[]', usage jsonb not null default '{}', exclusivity jsonb not null default '{}', term_start date, term_end date, payment_terms text, cancellation_terms text, evidence jsonb not null default '{}', created_at timestamptz not null default now());
create table public.redline_rules (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, creator_id uuid references public.creators(id) on delete cascade, name text not null, category text not null, severity public.deal_severity not null default 'medium', rule jsonb not null, active boolean not null default true, created_at timestamptz not null default now());
create table public.counter_drafts (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id) on delete cascade, deal_id uuid not null references public.inbound_deals(id) on delete cascade, created_by uuid not null references public.users(id), subject text not null, body text not null, status public.draft_status not null default 'draft', model_name text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index on public.creators(organization_id); create index on public.inbound_deals(organization_id,status,received_at); create index on public.rate_cards(organization_id,creator_id);
create or replace function public.is_org_member(target uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.users where id=auth.uid() and organization_id=target); $$;
alter table public.organizations enable row level security; alter table public.users enable row level security; alter table public.creators enable row level security; alter table public.rate_cards enable row level security; alter table public.brand_contacts enable row level security; alter table public.inbound_deals enable row level security; alter table public.deal_terms enable row level security; alter table public.redline_rules enable row level security; alter table public.counter_drafts enable row level security;
create policy org_self on public.organizations for select using (public.is_org_member(id));
create policy users_same_org on public.users for all using (public.is_org_member(organization_id)) with check (public.is_org_member(organization_id));
create policy creators_same_org on public.creators for all using (public.is_org_member(organization_id)) with check (public.is_org_member(organization_id));
create policy rates_same_org on public.rate_cards for all using (public.is_org_member(organization_id)) with check (public.is_org_member(organization_id));
create policy contacts_same_org on public.brand_contacts for all using (public.is_org_member(organization_id)) with check (public.is_org_member(organization_id));
create policy deals_same_org on public.inbound_deals for all using (public.is_org_member(organization_id)) with check (public.is_org_member(organization_id));
create policy terms_same_org on public.deal_terms for all using (exists(select 1 from public.inbound_deals d where d.id=deal_id and public.is_org_member(d.organization_id))) with check (exists(select 1 from public.inbound_deals d where d.id=deal_id and public.is_org_member(d.organization_id)));
create policy rules_same_org on public.redline_rules for all using (public.is_org_member(organization_id)) with check (public.is_org_member(organization_id));
create policy drafts_same_org on public.counter_drafts for all using (public.is_org_member(organization_id)) with check (public.is_org_member(organization_id));
